shader.vertex:
in vec2 poz;

uniform mat4 matrix;

out vec2 uv;

void main()
{
  uv = poz;
  gl_Position = matrix * vec4(poz - vec2(.5, .5), 0.0, 1.0);
}

shader.fragment:
in vec2 uv;

uniform vec4 color;
uniform sampler2D tex;
uniform bool use_tex;

out vec4 color_o;

void main()
{
  if (use_tex)
    color_o = texture(tex, uv) * color;
  else
    color_o = color;
}
